import sys

data = sys.stdin.read().split()
n, K = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]

def seg(l, r):
    s = a[l:r + 1]
    return max(s) - min(s) + abs(s[0] - s[-1])

def rec(start, parts):
    if parts == 1:
        return seg(start, n - 1)
    best = None
    for end in range(start, n - parts + 1):
        v = seg(start, end) + rec(end + 1, parts - 1)
        if best is None or v < best:
            best = v
    return best

print(rec(0, K))

